// Heat-vision index — record JAH-GAIS-WEARABLETHERMAL-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"thermal_px": 19200, "temp_range_c": 400, "price_usd": 250};
var value = (m.thermal_px*m.temp_range_c/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAIS-WEARABLETHERMAL-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAIS-WEARABLETHERMAL-000001|' + value.toFixed(2) + ' heat-vision index');

